pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(caller != address(0));
        amount = bound(amount, 0, 100 ether);

        vm.deal(caller, amount + 1 ether);

        bool ok;
        vm.prank(caller);
        (ok, ) = address(c).call{value: amount}("");

        assertTrue(ok == (amount == 10 ether));
    }
}
